    AwsDmsEndpointDetails.add_member(:endpoint_type, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'EndpointType', traits: {"smithy.api#documentation" => "<p>\n            The type of endpoint. Valid values are source and target.\n        </p>"}))
    AwsDmsEndpointDetails.add_member(:engine_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'EngineName', traits: {"smithy.api#documentation" => "<p>\n            The type of engine for the endpoint, depending on the <code>EndpointType</code> value.\n        </p>"}))
    AwsDmsEndpointDetails.add_member(:external_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'ExternalId', traits: {"smithy.api#documentation" => "<p>\n            A value that can be used for cross-account validation.\n        </p>"}))
    AwsDmsEndpointDetails.add_member(:extra_connection_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'ExtraConnectionAttributes', traits: {"smithy.api#documentation" => "<p>\n            Additional attributes associated with the connection.\n        </p>"}))
    AwsDmsEndpointDetails.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>\n            An DMS key identifier that is used to encrypt the connection parameters for the endpoint.\n            If you don't specify a value for the <code>KmsKeyId</code> parameter, then DMS uses your default \n            encryption key. KMS creates the default encryption key for your Amazon Web Services account. Your \n            Amazon Web Services account has a different default encryption key for each Amazon Web Services Region.</p>"}))
    AwsDmsEndpointDetails.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>\n            The port used to access the endpoint.\n        </p>"}))
    AwsDmsEndpointDetails.add_member(:server_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'ServerName', traits: {"smithy.api#documentation" => "<p>\n            The name of the server where the endpoint database resides.</p>"}))
