    AwsDmsEndpointDetails.add_member(:username, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'Username', traits: {"smithy.api#documentation" => "<p>\n            The user name to be used to log in to the endpoint database.\n        </p>"}))
    AwsDmsEndpointDetails.type = Types::AwsDmsEndpointDetails
    AwsDmsReplicationInstanceDetails.add_member(:allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'AllocatedStorage', traits: {"smithy.api#documentation" => "<p>\n            The amount of storage (in gigabytes) that is allocated for the replication instance.\n        </p>"}))
    AwsDmsReplicationInstanceDetails.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>\n        Indicates whether minor engine upgrades are applied automatically to the replication instance during the maintenance \n        window.\n        </p>"}))
    AwsDmsReplicationInstanceDetails.add_member(:availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'AvailabilityZone', traits: {"smithy.api#documentation" => "<p>\n            The Availability Zone that the replication instance is created in. The default value is a random, system-chosen \n            Availability Zone in the endpoint's Amazon Web Services Region, such as <code>us-east-1d</code>.</p>"}))
    AwsDmsReplicationInstanceDetails.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>\n            The engine version number of the replication instance. If an engine version number is not specified when a \n            replication instance is created, the default is the latest engine version available.\n        </p>"}))
    AwsDmsReplicationInstanceDetails.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>\n            An KMS key identifier that is used to encrypt the data on the replication instance. If you don't \n            specify a value for the <code>KmsKeyId</code> parameter, DMS uses your default encryption key. \n            KMS creates the default encryption key for your Amazon Web Services account. Your \n            Amazon Web Services account has a different default encryption key for each Amazon Web Services Region.</p>"}))
