    AwsEcsServiceDetails.add_member(:propagate_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'PropagateTags', traits: {"smithy.api#documentation" => "<p>Indicates whether to propagate the tags from the task definition to the task or from the service to the task. If no value is provided, then tags are not propagated.</p>\n         <p>Valid values: <code>TASK_DEFINITION</code> | <code>SERVICE</code>\n         </p>"}))
    AwsEcsServiceDetails.add_member(:role, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'Role', traits: {"smithy.api#documentation" => "<p>The ARN of the IAM role that is associated with the service. The role allows the Amazon ECS container agent to register container instances with an Elastic Load Balancing load balancer.</p>"}))
    AwsEcsServiceDetails.add_member(:scheduling_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'SchedulingStrategy', traits: {"smithy.api#documentation" => "<p>The scheduling strategy to use for the service.</p>\n         <p>The <code>REPLICA</code> scheduling strategy places and maintains the desired number of tasks across the cluster. By default, the service scheduler spreads tasks across Availability Zones. Task placement strategies and constraints are used to customize task placement decisions.</p>\n         <p>The <code>DAEMON</code> scheduling strategy deploys exactly one task on each active container instance that meets all of the task placement constraints that are specified in the cluster. The service scheduler also evaluates the task placement constraints for running tasks and stops tasks that don't meet the placement constraints.</p>\n         <p>Valid values: <code>REPLICA</code> | <code>DAEMON</code>\n         </p>"}))
