    AwsEcsServiceServiceRegistriesDetails.add_member(:container_port, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ContainerPort', traits: {"smithy.api#documentation" => "<p>The port value to use for the service discovery service.</p>\n         <p>If the task definition uses the <code>bridge</code> or <code>host</code> network mode, you must specify <code>ContainerName</code> and <code>ContainerPort</code>.</p>\n         <p>If the task definition uses the <code>awsvpc</code> network mode and a type SRV DNS record, you must specify either <code>ContainerName</code> and <code>ContainerPort</code>, or <code>Port</code> , but not both.</p>"}))
