    AwsSecurityFinding.add_member(:product_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'ProductArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ARN generated by Security Hub that uniquely identifies a product that generates findings.\n         This can be the ARN for a third-party product that is integrated with Security Hub, or the ARN for\n         a custom integration.</p>\n         <p>Length Constraints: Minimum length of 12. Maximum length of 2048.</p>", "smithy.api#required" => {}}))
    AwsSecurityFinding.add_member(:product_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'ProductName', traits: {"smithy.api#documentation" => "<p>The name of the product that generated the finding.</p>\n         <p>Security Hub populates this attribute automatically for each finding. You cannot update this attribute with <code>BatchImportFindings</code> or <code>BatchUpdateFindings</code>. The exception to this is a custom integration.</p>\n         <p>When you use the Security Hub console or API to filter findings by product name, you use this attribute.</p>\n         <p>Length Constraints: Minimum length of 1. Maximum length of 128.</p>"}))
    AwsSecurityFinding.add_member(:company_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'CompanyName', traits: {"smithy.api#documentation" => "<p>The name of the company for the product that generated the finding.</p>\n         <p>Security Hub populates this attribute automatically for each finding. You cannot update this attribute with <code>BatchImportFindings</code> or <code>BatchUpdateFindings</code>. The exception to this is a custom integration.</p>\n         <p>When you use the Security Hub console or API to filter findings by company name, you use this attribute.</p>\n         <p>Length Constraints: Minimum length of 1. Maximum length of 128.\n       </p>"}))
    AwsSecurityFinding.add_member(:region, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'Region', traits: {"smithy.api#documentation" => "<p>The Region from which the finding was generated.</p>\n         <p>Security Hub populates this attribute automatically for each finding. You cannot update it using <code>BatchImportFindings</code> or <code>BatchUpdateFindings</code>.</p>\n         <p>Length Constraints: Minimum length of 1. Maximum length of 16.\n       </p>"}))
    AwsSecurityFinding.add_member(:generator_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'GeneratorId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the solution-specific component (a discrete unit of logic) that\n         generated a finding. In various security findings providers' solutions, this generator can\n         be called a rule, a check, a detector, a plugin, or something else.</p>\n         <p>Length Constraints: Minimum length of 1. Maximum length of 512.</p>", "smithy.api#required" => {}}))
    AwsSecurityFinding.add_member(:aws_account_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'AwsAccountId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Web Services account ID that a finding is generated in.</p>\n         <p>Length Constraints: 12.</p>", "smithy.api#required" => {}}))
    AwsSecurityFinding.add_member(:types, Smithy::Schema::Shapes::ShapeRef.new(shape: TypeList, location_name: 'Types', traits: {"smithy.api#documentation" => "<p>One or more finding types in the format of <code>namespace/category/classifier</code>\n         that classify a finding.</p>\n         <p>Valid namespace values are: Software and Configuration Checks | TTPs | Effects | Unusual\n         Behaviors | Sensitive Data Identifications</p>\n         <p>Array Members: Maximum number of 50 items.</p>"}))
