    AwsSecurityFinding.add_member(:title, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'Title', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A finding's title. <code>Title</code> is a required property.</p>\n         <p>Length Constraints: Minimum length of 1. Maximum length of 256.</p>", "smithy.api#required" => {}}))
