    AwsSecurityFinding.add_member(:compliance, Smithy::Schema::Shapes::ShapeRef.new(shape: Compliance, location_name: 'Compliance', traits: {"smithy.api#documentation" => "<p>This data type is exclusive to findings that are generated as the result of a check run\n         against a specific rule in a supported security standard, such as CIS Amazon Web Services Foundations.\n         Contains security standard-related finding details.</p>"}))
