    SeverityUpdate.add_member(:normalized, Smithy::Schema::Shapes::ShapeRef.new(shape: RatioScale, location_name: 'Normalized', traits: {"smithy.api#documentation" => "<p>The normalized severity for the finding. This attribute is to be deprecated in favor of\n            <code>Label</code>.</p>\n         <p>If you provide <code>Normalized</code> and don't provide <code>Label</code>,\n            <code>Label</code> is set automatically as follows.</p>\n         <ul>\n            <li>\n               <p>0 - <code>INFORMATIONAL</code>\n               </p>\n            </li>\n            <li>\n               <p>1–39 - <code>LOW</code>\n               </p>\n            </li>\n            <li>\n               <p>40–69 - <code>MEDIUM</code>\n               </p>\n            </li>\n            <li>\n               <p>70–89 - <code>HIGH</code>\n               </p>\n            </li>\n            <li>\n               <p>90–100 - <code>CRITICAL</code>\n               </p>\n            </li>\n         </ul>"}))
