    UpdateAutomationRulesRequestItem.add_member(:rule_status, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleStatus, location_name: 'RuleStatus', traits: {"smithy.api#documentation" => "<p>\n         Whether the rule is active after it is created. If \n         this parameter is equal to <code>ENABLED</code>, Security Hub starts applying the rule to findings \n         and finding updates after the rule is created. To change the value of this\n         parameter after creating a rule, use <a href=\"https://docs.aws.amazon.com/securityhub/1.0/APIReference/API_BatchUpdateAutomationRules.html\">\n               <code>BatchUpdateAutomationRules</code>\n            </a>.\n      </p>"}))
    UpdateAutomationRulesRequestItem.add_member(:rule_order, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleOrderValue, location_name: 'RuleOrder', traits: {"smithy.api#documentation" => "<p> An integer ranging from 1 to 1000 that represents the order in which the rule action is\n         applied to findings. Security Hub applies rules with lower values for this parameter\n         first. </p>"}))
    UpdateAutomationRulesRequestItem.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>\n         A description of the rule.\n      </p>"}))
    UpdateAutomationRulesRequestItem.add_member(:rule_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'RuleName', traits: {"smithy.api#documentation" => "<p>\n         The name of the rule.\n      </p>"}))
    UpdateAutomationRulesRequestItem.add_member(:is_terminal, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'IsTerminal', traits: {"smithy.api#documentation" => "<p>Specifies whether a rule is the last to be applied with respect to a finding that matches the rule criteria. This is useful when a finding \n            matches the criteria for multiple rules, and each rule has different actions. If a rule is terminal, Security Hub applies the rule action to a finding that matches \n            the rule criteria and doesn't evaluate other rules for the finding. By default, a rule isn't terminal.\n        </p>"}))
