    UpdateConfigurationPolicyRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>\n            The name of the configuration policy. Alphanumeric characters and the following ASCII characters are permitted: \n            <code>-, ., !, *, /</code>.\n        </p>"}))
    UpdateConfigurationPolicyRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>\n            The description of the configuration policy.\n        </p>"}))
    UpdateConfigurationPolicyRequest.add_member(:updated_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'UpdatedReason', traits: {"smithy.api#documentation" => "<p>\n            The reason for updating the configuration policy.\n        </p>"}))
    UpdateConfigurationPolicyRequest.add_member(:configuration_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: Policy, location_name: 'ConfigurationPolicy', traits: {"smithy.api#documentation" => "<p>\n            An object that defines how Security Hub is configured. It includes whether Security Hub is enabled or \n            disabled, a list of enabled security standards, a list of enabled or disabled security controls, and a list of custom parameter values for specified controls. \n            If you provide a list of security controls that are enabled in the configuration policy, Security Hub disables all other controls (including newly \n            released controls). If you provide a list of security controls that are disabled in the configuration policy, Security Hub \n            enables all other controls (including newly released controls).\n        </p>\n         <p>When updating a configuration policy, provide a complete list of standards that you want to enable and a complete list \n            of controls that you want to enable or disable. The updated configuration replaces the current configuration.</p>"}))
    UpdateConfigurationPolicyRequest.type = Types::UpdateConfigurationPolicyRequest
    UpdateConfigurationPolicyResponse.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'Arn', traits: {"smithy.api#documentation" => "<p>\n            The ARN of the configuration policy.\n        </p>"}))
