    UpdateConfigurationPolicyResponse.add_member(:updated_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'UpdatedAt', traits: {"smithy.api#documentation" => "<p>\n            The date and time, in UTC and ISO 8601 format, that the configuration policy was last updated.\n        </p>"}))
