    Vulnerability.add_member(:reference_urls, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'ReferenceUrls', traits: {"smithy.api#documentation" => "<p>A list of URLs that provide additional information about the vulnerability.</p>"}))
    Vulnerability.add_member(:fix_available, Smithy::Schema::Shapes::ShapeRef.new(shape: VulnerabilityFixAvailable, location_name: 'FixAvailable', traits: {"smithy.api#documentation" => "<p>Specifies if all vulnerable packages in a finding have a value for <code>FixedInVersion</code> \nand <code>Remediation</code>.\nThis field is evaluated for each vulnerability <code>Id</code> based on the number of vulnerable packages that have a value for both \n<code>FixedInVersion</code> and <code>Remediation</code>. Valid values are as follows:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>YES</code> if all vulnerable packages have a value for both <code>FixedInVersion</code> and <code>Remediation</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>NO</code> if no vulnerable packages have a value for <code>FixedInVersion</code> and <code>Remediation</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>PARTIAL</code> otherwise</p>\n            </li>\n         </ul>"}))
